import React, { useState, useEffect } from 'react';
import Header from './components/layout/Header';
import Sidebar from './components/layout/Sidebar';
import PerformanceChart from './components/dashboard/PerformanceChart';
import CalendarFilter from './components/dashboard/CalendarFilter';
import { fetchAvailableDates, fetchJavelinDataByDate } from './services/api';

function App() {
  const [allAvailableDates, setAllAvailableDates] = useState([]);
  const [selectedThrows, setSelectedThrows] = useState({});
  const [comparisonData, setComparisonData] = useState([]);
  const [sidebarStats, setSidebarStats] = useState({});
  const [sidebarThrowDetails, setSidebarThrowDetails] = useState(null);
  const [comparisonStats, setComparisonStats] = useState([]);
  const [loading, setLoading] = useState(false);
  const [visibility, setVisibility] = useState({});

  useEffect(() => {
    const newVisibility = {};
    comparisonStats.forEach(stat => {
      newVisibility[stat.id] = true;
    });
    setVisibility(newVisibility);
  }, [comparisonStats]);

  const handleLegendClick = (dataKey) => {
    setVisibility(prev => ({ ...prev, [dataKey]: !prev[dataKey] }));
  };

  useEffect(() => {
    const getDates = async () => {
      try {
        const dates = await fetchAvailableDates();
        setAllAvailableDates(dates);
      } catch (error) {
        console.error("Failed to fetch dates:", error);
      }
    };
    getDates();
  }, []);

  useEffect(() => {
    const datesToFetch = Object.keys(selectedThrows);
    const totalSelectedCount = Object.values(selectedThrows).reduce((acc, throws) => acc + throws.length, 0);
    if (totalSelectedCount === 0) {
      setComparisonData([]); setSidebarStats({}); setSidebarThrowDetails(null); setComparisonStats([]);
      return;
    }
    const getDataForComparison = async () => {
      setLoading(true);
      const dateDataPromises = datesToFetch.map(date => fetchJavelinDataByDate(date));
      try {
        const fetchedDateResults = await Promise.all(dateDataPromises);
        const dateDataMap = new Map(datesToFetch.map((date, i) => [date, fetchedDateResults[i]]));
        const newChartData = [];
        const newComparisonStats = [];
        for (const date in selectedThrows) {
          const selectedIndices = selectedThrows[date];
          const dateData = dateDataMap.get(date);
          if (dateData?.throws) {
            selectedIndices.forEach(throwIndex => {
              const throwData = dateData.throws[throwIndex];
              if (throwData) {
                const throwId = `${date} - Throw ${throwIndex + 1}`;
                newChartData.push({ id: throwId, trajectory: throwData.trajectory });
                newComparisonStats.push({
                  id: throwId,
                  date: date,
                  throwNum: throwIndex + 1,
                  time: throwData.time,
                  playerStats: throwData.playerStats,
                });
              }
            });
          }
        }
        setComparisonData(newChartData);
        setComparisonStats(newComparisonStats);
        if (totalSelectedCount === 1) {
          const singleThrow = newComparisonStats[0];
          setSidebarStats(singleThrow.playerStats);
          setSidebarThrowDetails({ date: singleThrow.date, throwNum: singleThrow.throwNum, time: singleThrow.time });
        } else {
          setSidebarStats({});
          setSidebarThrowDetails(null);
        }
      } catch (error) {
        console.error("Failed to fetch comparison data:", error);
      } finally {
        setLoading(false);
      }
    };
    getDataForComparison();
  }, [selectedThrows]);

  const handleResetSelection = () => {
    setSelectedThrows({});
  };

  const totalSelectedCount = Object.values(selectedThrows).reduce((acc, throws) => acc + throws.length, 0);
  const isComparisonView = totalSelectedCount > 1;

  return (
    <div className="flex h-screen bg-background text-gray-800">
      <div className={`bg-white border-r border-gray-200 transition-all duration-300 ease-in-out`} style={{ width: isComparisonView ? '45%' : '320px', maxWidth: '600px' }}>
        <Sidebar 
          isComparisonView={isComparisonView}
          playerStats={sidebarStats} 
          throwDetails={sidebarThrowDetails}
          comparisonStats={comparisonStats}
          visibility={visibility}
          loading={loading && totalSelectedCount < 2}
        />
      </div>
      <div className="flex-1 flex flex-col">
        <Header />
        <main className="flex-1 p-8 overflow-y-auto">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Javelin Throw Analytics</h1>
          <p className="text-gray-500 mb-6">Select one or more throws from the calendar to begin comparison.</p>
          <CalendarFilter
            availableDates={allAvailableDates}
            selectedThrows={selectedThrows}
            onChange={setSelectedThrows}
            onReset={handleResetSelection}
          />
          <PerformanceChart 
            comparisonData={comparisonData} 
            visibility={visibility}
            onLegendClick={handleLegendClick}
            loading={loading} 
          />
        </main>
      </div>
    </div>
  );
}

export default App;
